style.css:
@-moz-document domain("roblox.com") {
:root {
    --rbx-bg: #0b0b0d;
    --rbx-surface: #131317;
    --rbx-text: #e5e5e5;
    --rbx-muted: #9a9a9a;
    --rbx-accent: #00a2ff; /* azul neon Roblox Premium */
    --rbx-radius: 6px;
  }

  /* Fundo global */
  html, body {
    background: var(--rbx-bg) !important;
    color: var(--rbx-text) !important;
  }

  /* Cabeçalho */
  .nav-container, 
  #navigation, 
  header, 
  .navbar {
    background: var(--rbx-surface) !important;
    border-bottom: 1px solid rgba(255,255,255,0.05) !important;
  }

  /* Texto geral */
  p, span, div, li, a, button, label {
    color: var(--rbx-text) !important;
  }

  /* Links e botões com brilho azul */
  a:hover, button:hover {
    color: var(--rbx-accent) !important;
  }

  button, .btn-primary {
    background: rgba(0,162,255,0.15) !important;
    border: 1px solid rgba(0,162,255,0.3) !important;
    border-radius: var(--rbx-radius) !important;
  }

  /* Cartões, listas e seções */
  .game-card-container,
  .game-card,
  .section,
  .content,
  .container,
  .rbx-carousel-item,
  .rbx-game-card {
    background: var(--rbx-surface) !important;
    border-radius: var(--rbx-radius) !important;
    border: 1px solid rgba(255,255,255,0.03) !important;
  }

  /* Imagem com leve realce */
  img {
    filter: brightness(1.07) contrast(1.04) !important;
  }

  /* Caixa de pesquisa e inputs */
  input, textarea, select {
    background: #1b1b1f !important;
    color: var(--rbx-text) !important;
    border: 1px solid rgba(255,255,255,0.08) !important;
  }

  /* Menus flutuantes */
  .dropdown-menu, .menu-area {
    background: var(--rbx-surface) !important;
    border: 1px solid rgba(255,255,255,0.05) !important;
  }

  /* Scrollbar estilizada */
  ::-webkit-scrollbar { width: 12px; }
  ::-webkit-scrollbar-track { background: var(--rbx-bg); }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, #00a2ff, #0060aa);
    border-radius: 999px;
    border: 2px solid #000;
  }

  /* Popups, banners e anúncios chatos */
  [class*="ad"], 
  [id*="ad"], 
  .advertisement, 
  .cookie-banner, 
  #cookie-banner {
    display: none !important;
  }
}
